const m=[{id:"low",label:"Sezon i ulët",labelEn:"Low Season",months:[1,2,11],multiplier:.85,badgeColor:"bg-blue-100 text-blue-700 border-blue-200",description:"Çmimet janë 15% më të ulëta gjatë muajve janar, shkurt dhe nëntor.",emoji:"❄️"},{id:"normal",label:"Sezon normal",labelEn:"Regular Season",months:[3,4,10,12],multiplier:1,badgeColor:"bg-neutral-100 text-neutral-600 border-neutral-200",description:"Çmimet standarde pa ndonjë shtesa ose zbritje sezonale.",emoji:"🌤️"},{id:"high",label:"Sezon i lartë",labelEn:"High Season",months:[5,6,9],multiplier:1.2,badgeColor:"bg-amber-100 text-amber-700 border-amber-200",description:"Kërkesa e lartë në maj, qershor dhe shtator: +20% mbi çmimin bazë.",emoji:"☀️"},{id:"peak",label:"Sezon kulminant",labelEn:"Peak Season",months:[7,8],multiplier:1.4,badgeColor:"bg-orange-100 text-orange-700 border-orange-200",description:"Korrik dhe gusht janë muajt me kërkesën më të lartë: +40% mbi çmimin bazë.",emoji:"🔥"}];function d(n=new Date){const a=n.getMonth()+1;return m.find(e=>e.months.includes(a))??m[1]}function j(n,a=new Date){const e=Number(n);if(!Number.isFinite(e))return 0;const t=d(a);return Math.round(e*t.multiplier*100)/100}function S(n,a,e){const t=[],s=Number.isFinite(Number(n))?Number(n):0,o=new Date(a);o.setHours(0,0,0,0);const b=new Date(e);b.setHours(0,0,0,0);const c=24*60*60*1e3,g=Math.max(1,Math.ceil((b.getTime()-o.getTime())/c));for(let i=0;i<g;i+=1){const r=d(o),u=Math.round(s*r.multiplier*100)/100,l=t.find(p=>p.season.id===r.id);l?(l.days+=1,l.subtotal=Math.round((l.subtotal+u)*100)/100):t.push({season:r,days:1,pricePerDay:u,subtotal:u}),o.setDate(o.getDate()+1)}const h=t.reduce((i,r)=>i+r.subtotal,0);return{total:Math.round(h*100)/100,breakdown:t}}function D(n,a){const{breakdown:e}=S(1,n,a);return e.length===0?m[1]:e.reduce((t,s)=>t.days>=s.days?t:s).season}export{d as a,D as b,S as c,j as g};
